// 6 messages, two models. Queue: claim-once (round robin). Topic: every subscriber gets all.
const msgs = ['m1', 'm2', 'm3', 'm4', 'm5', 'm6'];
const queueSeen = { A: 0, B: 0 };
msgs.forEach((m, i) => { queueSeen[i % 2 === 0 ? 'A' : 'B']++; }); // claimed once, acked, deleted
const topicSeen = { C: msgs.length, D: msgs.length };              // each gets every copy
const queueTotal = queueSeen.A + queueSeen.B;
const topicTotal = topicSeen.C + topicSeen.D;
console.log('queue: A=' + queueSeen.A + ' B=' + queueSeen.B + ' total=' + queueTotal);
console.log('topic: C=' + topicSeen.C + ' D=' + topicSeen.D + ' total=' + topicTotal);
